INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28201, 'Ephesians 5:30', 'Ephesians', 5, 30, '&nbsp;ځکه چې مونږ د هغۀ د بدن اندامونه يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28202, 'Ephesians 5:31', 'Ephesians', 5, 31, '&nbsp;”په دې وجه به سړے خپل مور پلار پرېږدى او د خپلې ښځې سره به يو ځائ شى، او دا دواړه به يو بدن شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28203, 'Ephesians 5:32', 'Ephesians', 5, 32, '&nbsp;دا يو لوئ راز دے خو زۀ يې د مسيح او جماعت په حقله وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28204, 'Ephesians 5:33', 'Ephesians', 5, 33, '&nbsp;بهرحال تاسو هر يو دې هم د خپلې ښځې سره د خپل ځان په شان مينه کوى، او ښځه دې هم د خپل خاوند عزت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28205, 'Ephesians 6:1', 'Ephesians', 6, 1, '&nbsp;اے بچو، په مالِک کښې د خپل مور او پلار حُکم منئ ځکه چې دا نېک کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28206, 'Ephesians 6:2', 'Ephesians', 6, 2, '&nbsp;”د خپل مور او پلار عزت کوئ.“ ځکه چې دا اولنے حُکم دے چې په کښې دا وعده شوې ده چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28207, 'Ephesians 6:3', 'Ephesians', 6, 3, '&nbsp;”تۀ به خوشحاله او دُنيا کښې به دې عمر ډېر وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28208, 'Ephesians 6:4', 'Ephesians', 6, 4, '&nbsp;او اے پلارانو، تاسو خپلو بچو له غصه مۀ ورولئ بلکې د هغوئ تربيت، نصيحت او پالنه د مالِک په طريقه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28209, 'Ephesians 6:5', 'Ephesians', 6, 5, '&nbsp;اے غلامانو، د خپلو مالِکانو تابعدارى په يره او عزت او صفا زړۀ سره کوئ، دغه شان لکه څنګه چې د مسيح تابعدارى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28210, 'Ephesians 6:6', 'Ephesians', 6, 6, '&nbsp;تل د هغوئ د خوشحالولو کوشش کوئ، نۀ صرف په هغه وخت کله چې هغوئ تاسو ته ګورى، بلکې د مسيح د غلامانو په توګه د زړۀ د اخلاصه د خُدائ پاک رضا پوره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28211, 'Ephesians 6:7', 'Ephesians', 6, 7, '&nbsp;په شوق سره خِدمت کوئ داسې لکه چې د خلقو نه بلکې لکه چې د مالِک خدمت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28212, 'Ephesians 6:8', 'Ephesians', 6, 8, '&nbsp;ځکه تاسو په دې پوهه شئ چې مالِک به مونږ هر يو له زمونږ د ښۀ کارونو اجر راکړى، هغه کۀ غلامان يُو او کۀ آزاد يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28213, 'Ephesians 6:9', 'Ephesians', 6, 9, '&nbsp;اے مالِکانو، تاسو هم د خپلو غلامانو سره داسې سلوک کوئ. هغوئ له دهمکى مۀ ورکوئ. ځکه چې تاسو ته پته ده چې ستاسو دواړو په آسمان کښې مالِک يو دے او هغه د چا طرفدارے هم نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28214, 'Ephesians 6:10', 'Ephesians', 6, 10, '&nbsp;آخر دا چې په مالِک کښې تکړه اوسئ او د هغۀ په قدرت کښې مضبوط اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28215, 'Ephesians 6:11', 'Ephesians', 6, 11, '&nbsp;د خُدائ پاک په ټولو وسلو ځان سمبال کړئ نو چې تاسو د دې قابل شئ چې د اِبليس د منصوبو خلاف ټينګ ودرېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28216, 'Ephesians 6:12', 'Ephesians', 6, 12, '&nbsp;ځکه چې زمونږ جنګ د انسان خلاف نه بلکې د بدکارو حکمرانانو، د اختيار د مالِکانو، د دُنيا د تيارو د قوتونو خلاف او د شېطانى ارواح خلاف دے چې په آسمانى ځايونو کښې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28217, 'Ephesians 6:13', 'Ephesians', 6, 13, '&nbsp;په دې وجه تاسو د خُدائ پاک په پوره وسلې ځان سمبال کړئ، نو چې تاسو د دې جوګه شئ چې په هغه بده ورځ د مقابلې دپاره ودرېږئ او ټول کارونه پوره کړئ او بيا هم قائم پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28218, 'Ephesians 6:14', 'Ephesians', 6, 14, '&nbsp;نو ځکه مضبوط ودرېږئ او د حقيقت پېټۍ د ملا نه تاؤ کړئ او د صداقت زغره واغوندئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28219, 'Ephesians 6:15', 'Ephesians', 6, 15, '&nbsp;خپل پېزار د سلامتۍ زيرے خورولو دپاره په پښو کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28220, 'Ephesians 6:16', 'Ephesians', 6, 16, '&nbsp;او د دې ټولو سره د ايمان ډالونه هم پورته کړئ چې د هغې په وسيله به تاسو د شېطان د شغلو ټول غشى مړۀ کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28221, 'Ephesians 6:17', 'Ephesians', 6, 17, '&nbsp;او د خلاصون ټوپۍ او د روحُ القُدس تُوره راواخلئ کوم چې د خُدائ پاک کلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28222, 'Ephesians 6:18', 'Ephesians', 6, 18, '&nbsp;او همېشه په هره موقع په روحُ القُدس کښې دُعا او زارى کوئ، او بېدار اوسئ او د ټولو مقدسينو دپاره بې‌ناغې دُعا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28223, 'Ephesians 6:19', 'Ephesians', 6, 19, '&nbsp;او زما دپاره هم دُعا کوئ چې کله زۀ خبرې کوم چې ما له داسې کلام راکړے شى چې زۀ پرې په زړۀ ورتيا سره د زيرى رازونه څرګند کړم', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28224, 'Ephesians 6:20', 'Ephesians', 6, 20, '&nbsp;د کوم دپاره چې زۀ په زنځيرونو تړلے سفير يم. دُعا کوئ چې زۀ په داسې زړۀ ورتيا سره دا پېغام ورکړم څنګه چې په ما فرض دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28225, 'Ephesians 6:21', 'Ephesians', 6, 21, '&nbsp;نو تاسو ته به د دې هم پته ولګى چې زۀ څنګه يم، او څۀ کوم. تخيکوس چې خوږ ورور دے او د مالِک په کار کښې ايماندار خادِم دے، هغه به تاسو ته هر څۀ ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28226, 'Ephesians 6:22', 'Ephesians', 6, 22, '&nbsp;زۀ هغه تاسو ته د دې مقصد دپاره درلېږم چې تاسو زمونږ د حالت نه خبر شئ او چې هغه ستاسو زړونو ته ډاډګيرنه درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28227, 'Ephesians 6:23', 'Ephesians', 6, 23, '&nbsp;د خُدائ پلار او د مالِک عيسىٰ مسيح د طرف نه، دې وروڼو ته سلامتى وى او په هغوئ کښې دې د ايمان مينه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28228, 'Ephesians 6:24', 'Ephesians', 6, 24, '&nbsp;په هغوئ ټولو دې فضل وى څوک چې زمونږ مالِک عيسىٰ مسيح سره نۀ ختمېدونکې مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28229, 'Philippians 1:1', 'Philippians', 1, 1, '&nbsp;دا خط د پولوس او تيموتيوس د طرف نه څوک چې د عيسىٰ مسيح خادِمان دى. زۀ دا د فيليپى هغه ټولو مقدسينو ته ليکم چې په عيسىٰ مسيح يې ايمان دے سره د هغوئ د مشرانو او خادِمانو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28230, 'Philippians 1:2', 'Philippians', 1, 2, '&nbsp;په تاسو دې زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح د طرف نه فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28231, 'Philippians 1:3', 'Philippians', 1, 3, '&nbsp;ما ته چې هرکله تاسو راياد شئ نو زۀ د خپل خُدائ پاک شُکر وباسم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28232, 'Philippians 1:4', 'Philippians', 1, 4, '&nbsp;او په هره يوه دُعا کښې چې زۀ يې ستاسو دپاره غواړم تل ډېر په خوشحالۍ تاسو ټولو دپاره خواست کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28233, 'Philippians 1:5', 'Philippians', 1, 5, '&nbsp;ځکه چې تاسو د اولنۍ ورځې نه تر ننه پورې د زيرى په خورولو کښې ما سره شريک يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28234, 'Philippians 1:6', 'Philippians', 1, 6, '&nbsp;زۀ په دې مطمئن يم چا چې په تاسو کښې نېک کار شروع کړے دے، هغه به يې د عيسىٰ مسيح تر ورځې پورې پوره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28235, 'Philippians 1:7', 'Philippians', 1, 7, '&nbsp;ځکه خو ما ته دا جائز دى چې زۀ ستاسو ټولو په حقله هم دغه شان خيال وکړم دپاره د دې چې تاسو زما په زړۀ کښې يئ، او زما د قېد او د زيرى د دفاع او په تصديق کښې تاسو ټول ما سره د خُدائ پاک په فضل کښې شريک يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28236, 'Philippians 1:8', 'Philippians', 1, 8, '&nbsp;خُدائ پاک زما ګواه دے چې زۀ څومره د عيسىٰ مسيح په مينه کښې ستاسو ټولو د ليدلو خواهشمند يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28237, 'Philippians 1:9', 'Philippians', 1, 9, '&nbsp;او زۀ دا دُعا کوم چې ستاسو مينه دې د عِلم او پوره پوهې سره نوره هم زياته شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28238, 'Philippians 1:10', 'Philippians', 1, 10, '&nbsp;چې تاسو داسې فېصله وکړے شئ څۀ چې ښۀ وى او چې تاسو د مسيح د واپسۍ تر ورځې پاک او بې‌عېبه پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28239, 'Philippians 1:11', 'Philippians', 1, 11, '&nbsp;او تاسو دې د صداقت مېوه ونيسئ کومه چې د عيسىٰ مسيح په وسيله ملاويږى او د خُدائ پاک جلال او ستائينه دې ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28240, 'Philippians 1:12', 'Philippians', 1, 12, '&nbsp;اے وروڼو، زۀ غواړم چې تاسو په دې خبر شئ څۀ چې په ما تير شول په حقيقت کښې هم هغه د زيرى د خورولو سبب شُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28241, 'Philippians 1:13', 'Philippians', 1, 13, '&nbsp;تر دې چې د قيصر د قلعې ټولو محافظانو او نورو ټولو خلقو ته دا پته ولګېده چې زۀ د مسيح دپاره قېدى يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28242, 'Philippians 1:14', 'Philippians', 1, 14, '&nbsp;او په مالِک کښې زمونږ زيات وروڼه او خوېندې زما د قېدېدو په وجه زړَور شول او بې‌يرې د خُدائ پاک کلام په اورولو کښې زړۀ ورتيا ښکاره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28243, 'Philippians 1:15', 'Philippians', 1, 15, '&nbsp;ځينې د مسيح پېغام په حسد او د مخالفت په وجه خو ځينې يې په نېک نيتۍ سره بيانوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28244, 'Philippians 1:16', 'Philippians', 1, 16, '&nbsp;دوئ د مينې په وجه د مسيح پېغام ورکوى او په دې خبر دى چې زۀ د زيرى د دفاع دپاره دلته يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28245, 'Philippians 1:17', 'Philippians', 1, 17, '&nbsp;خو ځينې د مسيح دعوىٰ د خود غرضۍ په وجه کوى او د صفا زړۀ نه يې نۀ کوى، بلکې په دې اراده يې کوى چې په جيل کښې زما مصيبتونه نور هم زيات شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28246, 'Philippians 1:18', 'Philippians', 1, 18, '&nbsp;خو دا څۀ خبره نۀ ده، خو خاص خبره دا ده چې د مسيح پېغام ورکول دى هغه چې په هره طريقه وى، هغه کۀ په بهانه يا په صفا زړۀ، او هم په دې کولو زۀ خوشحالېږم. آو، او همېشه به خوشحاله شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28247, 'Philippians 1:19', 'Philippians', 1, 19, '&nbsp;نو زۀ په دې پوهېږم چې ستاسو د دُعاګانو په وجه او د عيسىٰ مسيح د روح مدد به زما د آزادۍ سبب شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28248, 'Philippians 1:20', 'Philippians', 1, 20, '&nbsp;ځکه خو دغه زما د زړۀ خواهش او اُميد دے چې زۀ په څۀ خبره کښې هم شرمنده نۀ شم، بلکې زۀ به د مسيح دپاره خپله زړۀ ورتيا جارى وساتم، لکه څنګه چې مخکښې وم. او زۀ په دې يقين ساتم چې زما ژوند به د مسيح دپاره د عزت سبب وى، هغه کۀ زۀ مړ يم او يا کۀ ژوندے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28249, 'Philippians 1:21', 'Philippians', 1, 21, '&nbsp;مسيح زما دپاره ژوندون دے او مرګ زما دپاره ګټه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28250, 'Philippians 1:22', 'Philippians', 1, 22, '&nbsp;خو کۀ زۀ ژوندے پاتې شم نو نور فائده مند به خدمت وکړے شم. نو زۀ نۀ شم وئيلے چې زما دپاره څۀ غوره دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28251, 'Philippians 1:23', 'Philippians', 1, 23, '&nbsp;زۀ په يو دوه کښې حېران يم. زما زړۀ خو دا غواړى چې رُخصت شم او مسيح له لاړ شم ځکه چې دا ډېره زياته بهتره ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28252, 'Philippians 1:24', 'Philippians', 1, 24, '&nbsp;خو زما ژوندى پاتې کېدل ستاسو دپاره ډېر ضرورى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
