(28254, 'Philippians 1:26', 'Philippians', 1, 26, '&nbsp;کله چې زۀ تاسو له بيا راشم، نو په عيسىٰ مسيح کښې به تاسو سره لا زيات د فخر کولو دليلونه وى کوم چې هغه زما په وسيله کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28255, 'Philippians 1:27', 'Philippians', 1, 27, '&nbsp;صرف داسې اخلاق کوئ چې ستاسو ژوند دې د مسيح د زيرى په مطابق وى، نو بيا کۀ زۀ راشم او يا رانۀ شم، خو چې ستاسو په حقله دا واورم چې تاسو په يو روح کښې قائم يئ، او د اِنجيل د ايمان دپاره په يو زړۀ ښۀ خوارى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28256, 'Philippians 1:28', 'Philippians', 1, 28, '&nbsp;او په هيڅ خبره کښې هم د خپلو مخالفينو نه مۀ يرېږئ، ځکه چې دا د هغوئ دپاره د تباهۍ نښه ده، خو ستاسو دپاره دا د خُدائ پاک د طرف نه خلاصون دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28257, 'Philippians 1:29', 'Philippians', 1, 29, '&nbsp;ځکه چې تاسو ته دا امتياز نۀ صرف په مسيح د ايمان په وجه درکړے شو، بلکې دا چې د هغۀ د خاطره تکليفونه هم وزغمئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
